import {KINGDOMS,STANCES,EVENTS,createGame,act,chance,allies,affordable} from './game.mjs';
import {createWorld} from './world.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm4 5-2.5 5.5L8 16l2.5-5.5L16 8Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M8 12l3 3 5-6',book:'M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3V4Z M12 6v15',help:'M9 8a3 3 0 1 1 5 2.2c-1.2.9-2 1.3-2 3 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',settings:'M10 3h4l1 3 3 1 2 3-2 2v3l-3 2-1 3h-4l-1-3-3-1-2-3 2-2V8l3-2 1-3Z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',storm:'M7 14H5a4 4 0 1 1 1-7 6 6 0 0 1 11-1 4 4 0 1 1 2 8h-4 M12 11l-3 6h5l-3 5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',focus:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5 M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',route:'M5 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M19 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M7 5h9a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h9',laurel:'M7 3C0 7 3 19 11 20 M17 3c7 4 4 16-4 17 M3 9l4 1 M4 15l4-1 M21 9l-4 1 M20 15l-4-1 M12 6l1.5 3 3.5.5-2.5 2.5.5 3.5-3-1.7L9 15.5l.5-3.5L7 9.5l3.5-.5L12 6Z',mouse:'M12 3a6 6 0 0 0-6 6v6a6 6 0 0 0 12 0V9a6 6 0 0 0-6-6Z M12 3v7',coins:'M15 3c4 0 7 1.3 7 3s-3 3-7 3-7-1.3-7-3 3-3 7-3Z M8 6v4 M22 6v5c0 2-3 3-7 3 M22 11v5c0 2-3 3-7 3 M7 11c3.3 0 6 1.3 6 3s-2.7 3-6 3-6-1.3-6-3 2.7-3 6-3Z M1 14v5c0 1.7 2.7 3 6 3s6-1.3 6-3v-5',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Z M3 7l9 4 9-4 M12 11v11 M7 5l9 4',hourglass:'M6 3h12 M6 21h12 M7 3v5l5 4-5 4v5 M17 3v5l-5 4 5 4v5',close:'m6 6 12 12 M18 6 6 18',ship:'M12 3v12 M12 4l7 7h-7 M9 7l-5 5h5 M3 15h18l-3 5H6l-3-5Z M2 22l3-1 3 1 4-1 4 1 3-1 3 1',gift:'M3 8h18v4H3V8Z M5 12v9h14v-9 M12 8v13 M12 8C4 8 6 1 10 4l2 4Z M12 8c8 0 6-7 2-4l-2 4Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',star:'m12 2 2.5 7.5H22l-6 5 2.5 7.5-6.5-4.5L5.5 22 8 14.5l-6-5h7.5L12 2Z',leaf:'M20 3C10 2 3 5 4 12c1 8 14 7 16-9Z M3 21 15 9',check:'m5 12 4 4L19 6',flag:'M5 22V3 M5 3c5-4 9 4 14 0v10c-5 4-9-4-14 0',anchor:'M12 8v13 M5 11H2v3a10 10 0 0 0 20 0v-3h-3 M12 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.compass}"/></svg>`;
function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));}
let state=createGame(),tab='map',world=null,routes=true,audioCtx=null,ambient=null;
const SAVE_KEY='tides-envoy-save-v1';
function isValidSave(s){return s&&s.version===1&&['turn','ap','gold','supply','renown','storm','seed'].every(key=>Number.isFinite(s[key])&&s[key]>=0)&&s.turn<=25&&s.ap<=3&&s.gold<=1e7&&s.supply<=99&&s.renown<=100&&s.storm<=100&&Array.isArray(s.log)&&s.log.length<=80&&s.log.every(e=>e&&Number.isInteger(e.turn)&&e.turn>=1&&e.turn<=25&&typeof e.text==='string'&&e.text.length<=2000&&['action','event','story','diplomacy'].includes(e.kind))&&s.kingdoms&&Object.keys(s.kingdoms).length===KINGDOMS.length&&Object.keys(s.kingdoms).every(id=>KINGDOMS.some(k=>k.id===id))&&typeof s.mediated==='boolean'&&['harbor',...KINGDOMS.map(k=>k.id)].includes(s.location)&&KINGDOMS.some(k=>k.id===s.selected)&&(s.event===null||Number.isInteger(s.event)&&s.event>=0&&s.event<EVENTS.length)&&[null,'victory','defeat'].includes(s.result)&&KINGDOMS.every(k=>{const v=s.kingdoms?.[k.id];return v&&Number.isFinite(v.relation)&&v.relation>=0&&v.relation<=100&&['allied','trade','intel','quest'].every(key=>typeof v[key]==='boolean')&&Number.isFinite(v.retries)&&Number.isFinite(v.giftTurn);});}
try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const loaded=JSON.parse(raw);if(isValidSave(loaded))state=loaded;}}catch{}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('.save-state').innerHTML='<i></i>自动存档';}catch{$('.save-state').textContent='本次会话';}}
function toast(text,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=text;$('#toasts').append(n);setTimeout(()=>n.remove(),4700);}
function selected(){return KINGDOMS.find(k=>k.id===state.selected);}
function select(id){if(!KINGDOMS.some(k=>k.id===id))throw new Error('未知王国');state.selected=id;tab='map';render();save();if(innerWidth<=620)$('#kingdom-detail').scrollIntoView({behavior:'smooth',block:'start'});}
function run(type,p={}){const result=act(state,type,p);if(!result.ok){toast(result.error,true);return result;}state=result.state;if(dialog.open)closeDialog();save();render();toast(result.message);if(state.result)showEnding();else if(state.event!==null)showEvent();return result;}
function render(){
 $('#kingdom-list').innerHTML=KINGDOMS.map(d=>{const k=state.kingdoms[d.id];return `<button class="kingdom-item ${d.id===state.selected?'selected':''}" style="--kingdom:${d.color}" data-select="${d.id}" aria-label="查看${d.name}" aria-pressed="${d.id===state.selected}"><span class="crest">${d.symbol}</span><span class="kingdom-item-main"><b>${d.name}</b><small><i class="relation-dot"></i>${k.allied?'联盟成员':state.location===d.id?'使船停泊中':k.trade?'通商伙伴':k.relation>=55?'友好关系':'尚未结盟'}</small></span><span class="relation-number">${k.relation}</span></button>`;}).join('');
 $$('[data-select]').forEach(n=>n.onclick=()=>select(n.dataset.select));
 const d=selected(),k=state.kingdoms[d.id],here=state.location===d.id;
 $('#kingdom-detail').style.setProperty('--kingdom',d.color);
 $('#kingdom-detail').innerHTML=`<div class="detail-heading"><span class="status"><i></i>${here?'使船已抵达':'外交档案'}</span><span class="id">0${KINGDOMS.indexOf(d)+1} / V</span></div><div class="royal-hero"><span class="crest">${d.symbol}</span></div><div class="kingdom-title"><h2>${d.name}</h2><div class="en">${d.en}</div><div class="ruler">${d.ruler}</div></div><div class="trait-row"><span class="colored">${d.trait}</span><span>${k.allied?'盟约已缔结':k.trade?'自由贸易':'独立王国'}</span>${k.intel?'<span>情报已掌握</span>':''}</div><div class="relationship"><div class="relationship-head"><span>与你的外交关系</span><b>${k.relation} <small>/ 100</small></b></div><div class="meter"><i style="width:${k.relation}%"></i></div><div class="relationship-scale"><span>疏远</span><span>信任</span><span>亲密</span></div></div><blockquote class="quote">${d.quote}</blockquote><div class="bonus"><span data-icon="laurel"></span><span>联盟特权 · ${d.reward}</span></div><div class="detail-actions">${here?`<button class="primary-button" id="negotiate" ${k.allied&&k.trade?'disabled':''}><span data-icon="${k.allied?'coins':'shield'}"></span>${k.allied?(k.trade?'盟约与通商已生效':'商议通商协定'):'展开外交谈判'}</button><div class="action-split"><button class="secondary-button" id="gift" ${k.giftTurn===state.turn?'disabled':''}><span data-icon="gift"></span>赠送礼物</button><button class="secondary-button" id="intel" ${k.intel?'disabled':''}><span data-icon="eye"></span>${k.intel?'已获情报':'搜集情报'}</button></div><p class="action-note">赠礼 25 金币 · 情报 15 金币 · 各消耗 1 行动</p>`:`<button class="primary-button" id="sail"><span data-icon="ship"></span>航行至${d.short}</button><p class="action-note">${state.kingdoms.iron.allied?1:2} 份补给 · 1 次行动 · 即刻启航</p><button class="secondary-button" id="preview-negotiation"><span data-icon="shield"></span>查看谈判方案</button>`}<div class="action-split"><button class="secondary-button" id="resupply" title="1 行动换取 6 补给和 8 金币"><span data-icon="anchor"></span>整备船队</button><button class="secondary-button" id="speech" title="1 行动提高 5 声望"><span data-icon="flag"></span>和平演说</button></div><p class="action-note">整备：+6 补给、+8 金币 · 演说：+5 声望</p></div><div class="local-task"><div class="section-label"><span data-icon="book"></span><span>王国委托</span>${k.quest?'<span style="margin-left:auto;color:var(--green)">已完成</span>':''}</div><h4>${d.quest}</h4><p>${d.questText}<br>回报：关系 +18 · 声望 +7</p><button class="task-button" id="quest" ${k.quest||!here?'disabled':''}>${k.quest?'委托已完成':here?'援助王国 · 1 行动':'抵达后可接受委托'}</button></div>`;
 fillIcons();
 for(const action of ['sail','gift','intel','quest','resupply','speech']){const b=$('#'+action);if(b)b.onclick=()=>run(action,{id:d.id});}
 $('#negotiate')?.addEventListener('click',()=>showNegotiation());$('#preview-negotiation')?.addEventListener('click',()=>showNegotiation());
 $('#turn').textContent=String(Math.min(state.turn,24)).padStart(2,'0');$('#gold').textContent=state.gold;$('#supply').textContent=state.supply;$('#renown').textContent=state.renown;const income=18+Object.values(state.kingdoms).filter(x=>x.trade).length*8+(state.kingdoms.verdant.allied?15:0);$('#income').textContent=`+${income} / 回合`;
 $('#ap-pips').innerHTML=Array.from({length:3},(_,i)=>`<i class="${i<state.ap?'filled':''}"></i>`).join('');$('#ap-pips').setAttribute('aria-label',`剩余 ${state.ap} 次行动`);
 $('#storm-value').innerHTML=`${state.storm}<span> / 100</span>`;$('#storm-bar').style.width=state.storm+'%';$('#storm-description').textContent=state.storm<35?'暗潮初起，外交窗口依然敞开。':state.storm<65?'海域渐生动荡，盟约刻不容缓。':'风暴即将席卷群岛，尽快促成联盟。';
 $('#mission-count').textContent=`${allies(state)} / 4`;$('#mission-renown').textContent=`${state.renown} / 65`;$('#nav-allies').textContent=allies(state);$('#mission-pips').innerHTML=Array.from({length:4},(_,i)=>`<i class="${i<allies(state)?'filled':''}"></i>`).join('');
 $$('.nav-button').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));$('#end-turn').disabled=!!state.result||state.event!==null;world?.update(state);renderOverlay();
}
function renderOverlay(){const el=$('#map-overlay');el.hidden=tab==='map';if(tab==='map')return;
 const title=tab==='council'?'群岛联盟议会':'使者航海日志';el.innerHTML=`<div class="overlay-title"><div><span class="eyebrow">${tab==='council'?'THE ISLAND CONCORD':'THE ENVOY’S JOURNAL'}</span><h2>${title}</h2></div><button id="close-overlay" class="icon-button" aria-label="返回海图">${icon('close')}</button></div>`;
 if(tab==='council'){el.innerHTML+=`<p class="council-intro">已缔结 <b style="color:var(--gold)">${allies(state)}</b> 份盟约。至少联合四个王国、达到 65 声望，即可签署《群岛和平宪章》。</p>${KINGDOMS.map(d=>{const k=state.kingdoms[d.id];return `<button class="council-row" data-council-select="${d.id}" style="width:100%;text-align:left;--kingdom:${d.color}"><span class="crest">${d.symbol}</span><div><h3>${d.name}</h3><p>${k.allied?d.reward:`关系 ${k.relation} / 100 · ${k.trade?'通商协定已生效':'尚未建立商路'}`}</p></div><span class="pill">${k.allied?'已结盟':'查看'}</span></button>`;}).join('')}<div class="council-footer"><h3>${state.mediated?'海峡争端已和平解决':'赤珊与铁峭的海峡争端'}</h3><p>${state.mediated?'你促成了两个王国的和解，双方之间不再存在谈判惩罚。':'先与其中一方结盟，会令另一方谈判成功率降低 15%。以中立使者身份进行调停，可以消除这一影响。'}</p><button class="secondary-button" id="mediate" ${state.mediated?'disabled':''}>${state.mediated?'和平协定已签署':'召开调停会议 · 30 金币 / 1 行动'}</button>${!state.mediated?'<p style="margin-bottom:0;font-size:10px">需要至少 35 声望 · 双方关系 +10 · 声望 +6</p>':''}</div>`;$$('[data-council-select]').forEach(n=>n.onclick=()=>select(n.dataset.councilSelect));$('#mediate').onclick=()=>run('mediate');}
 else{const list=document.createElement('div');list.className='journal-list';for(const entry of state.log){const row=document.createElement('article');row.className='journal-entry';const small=document.createElement('small');small.textContent=`第 ${entry.turn} 回合 · ${entry.kind==='diplomacy'?'外交纪事':entry.kind==='event'?'海上见闻':'远征记录'}`;const p=document.createElement('p');p.textContent=entry.text;row.append(small,p);list.append(row);}el.append(list);}
 $('#close-overlay').onclick=()=>{tab='map';render();};
}
const dialog=$('#game-dialog');function openDialog(html,{locked=false}={}){$('#dialog-content').innerHTML=html;dialog.dataset.locked=String(locked);$('.dialog-close').hidden=locked;if(!dialog.open)dialog.showModal();fillIcons(dialog);}
function closeDialog(){dialog.close();}$('.dialog-close').onclick=closeDialog;dialog.addEventListener('cancel',e=>{if(dialog.dataset.locked==='true')e.preventDefault();});dialog.addEventListener('click',e=>{if(e.target===dialog&&dialog.dataset.locked!=='true'){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function showNegotiation(){const d=selected(),k=state.kingdoms[d.id];let stance=k.intel?d.stance:'trade',offer=0,pact=k.allied?'trade':'alliance';
 function draw(){const rate=chance(state,d.id,stance,offer,pact),here=state.location===d.id,needRelation=pact==='alliance'&&k.relation<55,already=pact==='alliance'?k.allied:k.trade,cost=offer+(pact==='alliance'?20:10),can=here&&!needRelation&&!already&&state.ap>0&&state.gold>=cost&&!state.result&&state.event===null;
 openDialog(`<span class="eyebrow">DIPLOMATIC AUDIENCE</span><h2 class="dialog-title">与${d.name}谈判</h2><p class="dialog-desc">${d.ruler}正在等候你的提案。选择符合对方利益的立场，会让谈判事半功倍。</p><div class="pact-tabs"><button data-pact="alliance" class="${pact==='alliance'?'active':''}">缔结联盟${k.allied?' · 已签署':''}</button><button data-pact="trade" class="${pact==='trade'?'active':''}">通商协定${k.trade?' · 已签署':''}</button></div><p class="dialog-label">选择外交立场</p><div class="stance-grid">${STANCES.map(x=>`<button class="stance-card ${stance===x.id?'active':''} ${k.intel&&d.stance===x.id?'recommended':''}" data-stance="${x.id}"><span>${icon(x.icon)}${x.name}</span><small>${k.intel&&d.stance===x.id?'情报：符合该国偏好 · +17%':x.desc}</small></button>`).join('')}</div><label class="offer-label"><input id="offer" type="checkbox" ${offer?'checked':''}>附赠 25 金币，表达善意 <span style="margin-left:auto;color:var(--gold)">+10%</span></label><div class="chance-panel"><div><span>提案接受概率</span><small>关系 ${k.relation} · 声望 ${state.renown}${k.intel?' · 情报 +12%':''}${k.retries?' · 重试 +'+Math.min(k.retries*8,24)+'%':''}</small></div><b class="chance-number">${rate}<small>%</small></b></div>${!here?'<div class="notice">使船尚未抵达此王国。航行到港后即可正式递交提案。</div>':needRelation?'<div class="notice">缔结联盟需要关系达到 55。赠礼、完成委托或先签署通商协定，都能改善关系。</div>':already?'<div class="notice">这项条约已经签署，并持续为你的远征带来收益。</div>':state.gold<cost?'<div class="notice">金币不足。整备船队或结束回合可获得收入。</div>':state.ap<=0?'<div class="notice">本轮行动力已用尽，请结束回合后继续谈判。</div>':''}<button class="primary-button" id="submit-negotiation" ${can?'':'disabled'}>${icon('shield')}递交${pact==='alliance'?'联盟':'通商'}提案</button><p class="negotiation-cost">消耗 1 次行动 · ${cost} 金币（无论成功与否均消耗）</p>`);
 $$('[data-stance]').forEach(n=>n.onclick=()=>{stance=n.dataset.stance;draw();});$$('[data-pact]').forEach(n=>n.onclick=()=>{pact=n.dataset.pact;draw();});$('#offer').onchange=e=>{offer=e.target.checked?25:0;draw();};$('#submit-negotiation').onclick=()=>{closeDialog();run('negotiate',{id:d.id,stance,offer,pact});};
 }draw();}
function showEvent(){const e=EVENTS[state.event];openDialog(`<span class="eyebrow">${e.tag} · SEA CHRONICLES</span><div class="dialog-emblem" style="margin-top:18px">≈</div><h2 class="dialog-title">${e.title}</h2><p class="dialog-desc">${e.text}</p>${e.choices.map((c,i)=>`<button class="event-choice" data-choice="${i}" ${affordable(state,c.cost)&&(!c.needsAlly||allies(state)>0)?'':'disabled'}><b>${c.title}</b><small>${c.detail}</small></button>`).join('')}<button class="text-button" data-choice="-1">暂缓处理 · 风暴危机 +4</button>`,{locked:true});$$('[data-choice]').forEach(n=>n.onclick=()=>{const choice=Number(n.dataset.choice);closeDialog();run('event',{choice});});}
function showEnding(){const win=state.result==='victory';openDialog(`<div class="endgame"><span class="eyebrow">${win?'THE ISLAND CONCORD':'THE END OF A VOYAGE'}</span><div class="dialog-emblem">${win?'✥':'≈'}</div><h2 class="dialog-title">${win?'让盟约照亮群海':'潮汐终将再次转向'}</h2><p class="dialog-desc">${win?'四面王国的旗帜在自由港一同升起。《群岛和平宪章》已经签署，而你，将被铭记为连接这片海洋的使者。':state.storm>=100?'席卷群岛的风暴关闭了外交窗口。这次航程未能达成盟约，但每一份经验都将照亮下一次远征。':'远征期限已至，群岛尚未达成共识。下一次航程，试着更早完成王国委托，并选择对方偏好的立场。'}</p><div class="score-grid"><div><b>${allies(state)}</b><small>缔结联盟</small></div><div><b>${state.renown}</b><small>外交声望</small></div><div><b>${Math.min(24,state.turn)}</b><small>远征回合</small></div></div><button class="primary-button" id="new-game">开启新的远征</button><button class="text-button" id="review-game">回顾群岛与航海日志</button></div>`);$('#new-game').onclick=newGame;$('#review-game').onclick=closeDialog;}
function newGame(){state=createGame();tab='map';closeDialog();world?.reset();world?.update(state,true);render();save();toast('新的远征开始了。先选择一个王国，扬帆出发。');}
function showGuide(){openDialog(`<span class="eyebrow">THE ENVOY’S HANDBOOK</span><h2 class="dialog-title">每一份盟约，都从信任开始。</h2><div class="guide-steps"><div class="guide-step"><b>01</b><div><strong>扬帆，拜访五个王国</strong><p>点击海图上的岛屿或左侧王国，再选择「航行」。每轮有 3 次行动，航行消耗 2 份补给。</p></div></div><div class="guide-step"><b>02</b><div><strong>了解诉求，争取信任</strong><p>完成王国委托可获得 18 关系与 7 声望。赠礼提高 12 关系；情报揭示偏好，并提高下一次谈判成功率。</p></div></div><div class="guide-step"><b>03</b><div><strong>交换利益，缔结盟约</strong><p>关系达到 55 后可提议结盟；通商协定没有关系门槛，每轮增加 8 金币。成功结盟获得独特特权、10 声望，并降低 8 危机。</p></div></div><div class="guide-step"><b>04</b><div><strong>在风暴前联合群岛</strong><p>在 24 回合内联合至少 4 个王国，并达到 65 声望即可获胜。危机达到 100 则失败。每 3 轮出现事件，每轮恢复行动、获得收入和 2 份补给。</p></div></div></div><div class="notice">补给或金币不足时，「整备船队」永远可以使用：1 次行动获得 6 补给、8 金币。谈判失败会给下次尝试积累 +8% 成功率。赤珊和铁峭的矛盾可在联盟议会中调停。</div><div class="keyboard-help"><kbd>H</kbd>使者手册 <kbd>Esc</kbd>关闭窗口 <span style="margin-left:auto">进度自动保存在当前浏览器</span></div><button class="primary-button" id="close-guide">回到群岛海图</button>`);$('#close-guide').onclick=closeDialog;}
function endTurn(){if(state.result){showEnding();return;}if(state.event!==null){showEvent();return;}if(state.ap>0){openDialog(`<span class="eyebrow">THE NEXT TIDE</span><h2 class="dialog-title">迎接下一轮潮汐？</h2><p class="dialog-desc">你还有 ${state.ap} 次行动未使用。结束回合后，剩余行动不会保留，所有行动力会恢复至 3。</p><div class="notice">商路收入与港口补给将在新回合结算。风暴危机会随时间上升，盟友可减缓它的增长。</div><button class="primary-button" id="confirm-end">确认结束回合</button><button class="text-button" id="continue-turn">继续当前回合</button>`);$('#confirm-end').onclick=()=>{closeDialog();run('end');};$('#continue-turn').onclick=closeDialog;}else run('end');}
function toggleAudio(){if(ambient){audioCtx.suspend();ambient=null;return;}try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();if(!audioCtx._started){const gain=audioCtx.createGain();gain.gain.value=.014;gain.connect(audioCtx.destination);for(const f of [110,164.81,220,261.63]){const osc=audioCtx.createOscillator();osc.frequency.value=f;osc.type='sine';osc.connect(gain);osc.start();}audioCtx._started=true;}ambient=true;}catch{toast('当前浏览器暂不支持环境音。',true);}}
function showSettings(){openDialog(`<span class="eyebrow">VOYAGE SETTINGS</span><h2 class="dialog-title">远征设置</h2><div class="settings-row"><span>海图航线<small>显示群岛间的航行路径</small></span><button id="settings-routes">${routes?'已显示':'已隐藏'}</button></div><div class="settings-row"><span>宁静环境音<small>轻柔的港口和弦 · 默认关闭</small></span><button id="settings-audio">${ambient?'已开启':'已关闭'}</button></div><div class="settings-row"><span>保存远征<small>进度自动保存在当前浏览器</small></span><button id="export-save">导出存档</button></div><div class="settings-row"><span>恢复远征<small>导入此前导出的存档文件</small></span><button id="import-save">导入存档</button><input id="save-file" type="file" accept="application/json,.json" hidden></div><div class="settings-row"><span>重新启航<small>清除当前远征，开始新的旅程</small></span><button id="reset-game">新游戏</button></div><button class="text-button" id="settings-close">返回游戏</button>`);$('#settings-routes').onclick=()=>{routes=!routes;world?.routes(routes);$('#toggle-routes').classList.toggle('enabled',routes);showSettings();};$('#settings-audio').onclick=()=>{toggleAudio();showSettings();};$('#export-save').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`群岛使者-第${state.turn}回合.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import-save').onclick=()=>$('#save-file').click();$('#save-file').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>100000)throw new Error();const candidate=JSON.parse(await file.text());if(!isValidSave(candidate))throw new Error();state=candidate;save();closeDialog();world?.update(state,true);render();toast('远征存档已恢复。');if(state.result)showEnding();else if(state.event!==null)showEvent();}catch{toast('无法读取此存档。请选择本游戏导出的有效 JSON 文件。',true);}};$('#reset-game').onclick=()=>{openDialog(`<span class="eyebrow">A NEW EXPEDITION</span><h2 class="dialog-title">开始新的远征？</h2><p class="dialog-desc">当前浏览器中的远征进度将被重置。你可以先从设置中导出存档，再开始新的旅程。</p><button class="primary-button" id="confirm-reset">确认重新启航</button><button class="text-button" id="cancel-reset">保留当前远征</button>`);$('#confirm-reset').onclick=newGame;$('#cancel-reset').onclick=showSettings;};$('#settings-close').onclick=closeDialog;}
$$('.nav-button').forEach(n=>n.onclick=()=>{tab=n.dataset.tab;render();});$('#help').onclick=showGuide;$('#guide-link').onclick=showGuide;$('#settings').onclick=showSettings;$('#end-turn').onclick=endTurn;$('#zoom-in').onclick=()=>world?.zoom(.86);$('#zoom-out').onclick=()=>world?.zoom(1.16);$('#reset-view').onclick=()=>world?.reset();$('#toggle-routes').onclick=()=>{routes=!routes;world?.routes(routes);$('#toggle-routes').classList.toggle('enabled',routes);};document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='h'&&!dialog.open&&!['INPUT','TEXTAREA'].includes(e.target.tagName))showGuide();});
fillIcons();render();try{world=createWorld($('#world'),select);world.update(state,true);}catch(e){console.error('3D renderer unavailable',e);$('#world-fallback').hidden=false;toast('已启用兼容海图模式，所有外交玩法仍然可用。');}
if(state.result)showEnding();else if(state.event!==null)showEvent();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_diplomatic_state',title:'读取群岛外交局势',description:'Read current resources, location, kingdoms, pending event, and expedition result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>structuredClone(state)},{name:'select_kingdom',title:'查看王国',description:'Select a kingdom on the map and show its diplomatic dossier. This does not sail or spend resources.',inputSchema:{type:'object',properties:{kingdom:{type:'string',enum:KINGDOMS.map(k=>k.id)}},required:['kingdom'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{select(input.kingdom);return {selected:state.selected};}},{name:'perform_diplomatic_action',title:'执行外交行动',description:'Perform an in-game action using the same costs and rules as the interface. Sailing spends an action and supplies; negotiations can fail. Event choice -1 postpones with a crisis penalty. Use read_diplomatic_state first.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['sail','gift','intel','quest','negotiate','resupply','speech','mediate','event','end']},kingdom:{type:'string',enum:KINGDOMS.map(k=>k.id)},stance:{type:'string',enum:STANCES.map(x=>x.id)},offer:{type:'integer',enum:[0,25]},pact:{type:'string',enum:['trade','alliance']},choice:{type:'integer',minimum:-1,maximum:1}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const r=run(input.action,{id:input.kingdom,stance:input.stance,offer:input.offer??0,pact:input.pact,choice:input.choice});if(!r.ok)throw new Error(r.error);return {message:r.message,turn:state.turn,actions:state.ap,gold:state.gold,supply:state.supply,renown:state.renown,allies:allies(state),result:state.result};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
